function normalizePositiveInteger(value: number | undefined, fallback: number) {
	return value === undefined || !Number.isFinite(value) || value <= 0
		? fallback
		: Math.max(1, Math.floor(value));
}

function normalizeMaxGetRetries(value: number | undefined) {
	return value === undefined || !Number.isFinite(value) || value < 0
		? MAX_GET_RETRIES
		: Math.floor(value);
}

function withTimeout<T>(
	operation: Promise<T>,
	timeoutMs: number,
	onTimeout: () => void,
	signal?: AbortSignal,
	onAbortOperation = onTimeout,
): Promise<T> {
	const promise = new Promise<T>((resolve, reject) => {
		let settled = false;
		const onAbort = () => {
			if (settled) return;
			settled = true;
			if (timer !== undefined) clearTimeout(timer);
			signal?.removeEventListener("abort", onAbort);
			onAbortOperation();
			reject(
				signal?.reason ?? new DOMException("Operation canceled", "AbortError"),
			);
		};
		const timer = Number.isFinite(timeoutMs)
			? setTimeout(
					() => {
						if (settled) return;
						settled = true;
						signal?.removeEventListener("abort", onAbort);
						onTimeout();
						reject(new DOMException("Operation timed out", "TimeoutError"));
					},
					Math.max(0, timeoutMs),
				)
			: undefined;
		operation.then(
			(value) => {
				if (settled) return;
				settled = true;
				if (timer !== undefined) clearTimeout(timer);
				signal?.removeEventListener("abort", onAbort);
				resolve(value);
			},
			<T>(error: T) => {
				if (settled) return;
				settled = true;
				if (timer !== undefined) clearTimeout(timer);
				signal?.removeEventListener("abort", onAbort);
				reject(error);
			},
		);
		if (signal?.aborted) onAbort();
		else signal?.addEventListener("abort", onAbort, { once: true });
	});
	return promise;
}

function getRequestContext(config: {
	method?: string;
	url?: string;
	params?: unknown;
	query?: unknown;
}) {
	const method = (config.method ?? "GET").toUpperCase();
	const endpoint = canonicalEndpointIdentity(config.url ?? "");
	const query = config.query ?? config.params;
	const page =
		query !== null && isObject(query) && "page" in query && isNumber(query.page)
			? query.page
			: undefined;
	return { method, endpoint, page };
}

