import { Duration, Effect, Schedule } from "effect";

import type { HevyHttpError } from "./hevy-http-error.js";
import {
	DEFAULT_RETRY_POLICY,
	getRetryDelayMs,
	type RetryPolicy,
} from "./retry-policy.js";

export type RetryScheduleInput = Pick<HevyHttpError, "status" | "headers">;

/**
 * Builds the Effect schedule used by retrying client programs.
 *
 * The schedule deliberately only owns retry timing and the retry count. The
 * client remains responsible for deciding whether an error is safe to retry,
 * preserving its HTTP execution metadata and observation lifecycle.
 */
export function createRetrySchedule(
	maxRetries: number,
	policy: RetryPolicy = DEFAULT_RETRY_POLICY,
	randomInt = (maxExclusive: number) =>
		Math.floor(Math.random() * maxExclusive),
): Schedule.Schedule<number, RetryScheduleInput> {
	return Schedule.recurs(Math.max(0, maxRetries)).pipe(
		Schedule.addDelay((metadata) =>
			Effect.sync(() => {
				return Duration.millis(
					getRetryDelayMs(metadata.input, metadata.attempt, policy, randomInt),
				);
			}),
		),
	);
}

import { Data, Duration, Effect } from "effect";

import type { HevyOperationSafety } from "./execution.js";

export interface BackoffFailureOptions {
	readonly cause: unknown;
	readonly method: string;
	readonly endpoint: string;
	readonly phase: "backoff";
	readonly operationSafety: HevyOperationSafety;
	readonly deadline?: number;
}

/** Internal typed failure used while adapting a retry wait. */
export class BackoffFailure extends Data.TaggedError("BackoffFailure")<{
	readonly cause: unknown;
	readonly method: string;
	readonly endpoint: string;
	readonly phase: "backoff";
	readonly operationSafety: HevyOperationSafety;
	readonly deadline?: number;
}> {}

function interruptionEffect(
	signal: AbortSignal,
): Effect.Effect<never, unknown> {
	return Effect.callback<never, unknown>((resume, interruptionSignal) => {
		const cleanup = () => {
			signal.removeEventListener("abort", fail);
			interruptionSignal.removeEventListener("abort", cleanup);
		};
		const fail = () =>
			resume(
				Effect.fail(
					signal.reason ?? new DOMException("Operation canceled", "AbortError"),
				),
			);
		if (signal.aborted) {
			fail();
			return;
		}
		signal.addEventListener("abort", fail, { once: true });
		interruptionSignal.addEventListener("abort", cleanup, { once: true });
		return Effect.sync(cleanup);
	}).pipe(Effect.interruptible);
}

/**
 * Wait using the Effect Clock while still observing the operation signal.
 * This is deliberately separate from the Promise adapter so TestClock can
 * control the actual production retry wait.
 */
export function effectClockSleep(
	delayMs: number,
	signal: AbortSignal,
): Effect.Effect<void, unknown> {
	if (signal.aborted) {
		return Effect.fail(
			signal.reason ?? new DOMException("Operation canceled", "AbortError"),
		);
	}
	const sleep = Effect.sleep(Duration.millis(Math.max(0, delayMs)));
	return Effect.raceFirst(sleep, interruptionEffect(signal)).pipe(
		Effect.asVoid,
	);
}

/**
 * Adapt the established Promise sleep hook to an interruptible Effect.
 * Synchronous throws are captured by tryPromise just like rejections.
 */
export function customPromiseSleep(
	delayMs: number,
	signal: AbortSignal,
	sleep: (milliseconds: number, signal?: AbortSignal) => Promise<void>,
): Effect.Effect<void, unknown> {
	return Effect.tryPromise({
		try: (interruptionSignal) => {
			if (signal.aborted) {
				return Promise.reject(
					signal.reason ?? new DOMException("Operation canceled", "AbortError"),
				);
			}
			return new Promise<void>((resolve, reject) => {
				let settled = false;
				const cleanup = () => {
					signal.removeEventListener("abort", onOperationAbort);
					interruptionSignal.removeEventListener("abort", onInterruptionAbort);
				};
				const settleReject = (cause: unknown) => {
					if (settled) return;
					settled = true;
					cleanup();
					reject(cause);
				};
				const onOperationAbort = () =>
					settleReject(
						signal.reason ??
							new DOMException("Operation canceled", "AbortError"),
					);
				const onInterruptionAbort = () =>
					settleReject(new DOMException("Effect interrupted", "AbortError"));
				signal.addEventListener("abort", onOperationAbort, { once: true });
				interruptionSignal.addEventListener("abort", onInterruptionAbort, {
					once: true,
				});
				if (signal.aborted) {
					onOperationAbort();
					return;
				}
				try {
					Promise.resolve(sleep(delayMs, signal)).then(() => {
						if (settled) return;
						settled = true;
						cleanup();
						resolve();
					}, settleReject);
				} catch (cause) {
					settleReject(cause);
				}
			});
		},
		catch: (cause) => cause,
	});
}

export function retryBackoff(
	options: BackoffFailureOptions & {
		readonly delayMs: number;
		readonly sleep?: (
			milliseconds: number,
			signal?: AbortSignal,
		) => Promise<void>;
		readonly signal: AbortSignal;
	},
): Effect.Effect<void, BackoffFailure> {
	const wait = options.sleep
		? customPromiseSleep(options.delayMs, options.signal, options.sleep)
		: effectClockSleep(options.delayMs, options.signal);
	return wait.pipe(
		Effect.mapError(
			(cause) =>
				new BackoffFailure({
					cause,
					method: options.method,
					endpoint: options.endpoint,
					phase: "backoff",
					operationSafety: options.operationSafety,
					deadline: options.deadline,
				}),
		),
	);
}

import {
	HEVY_DEADLINE_EXCEEDED_ERROR_CODE,
	HEVY_REQUEST_ABORTED_ERROR_CODE,
	HEVY_RETRY_EXHAUSTED_ERROR_CODE,
} from "./hevy-http-error.js";

/** Canonical identities for every endpoint template in the generated Hevy client. */
export type HevyEndpointTemplate =
	| "/v1/body_measurements"
	| "/v1/body_measurements/:date"
	| "/v1/exercise_history/:exerciseTemplateId"
	| "/v1/exercise_templates"
	| "/v1/exercise_templates/:exerciseTemplateId"
	| "/v1/routine_folders"
	| "/v1/routine_folders/:folderId"
	| "/v1/routines"
	| "/v1/routines/:routineId"
	| "/v1/user/info"
	| "/v1/workouts"
	| "/v1/workouts/:workoutId"
	| "/v1/workouts/count"
	| "/v1/workouts/events";

export type HevyEndpointIdentity = HevyEndpointTemplate | "unknown";
export type HevyDiagnosticEndpoint = HevyEndpointTemplate;
export type HevyMetricEndpoint = HevyEndpointTemplate | "unknown";

export const HEVY_ENDPOINT_TEMPLATES: readonly HevyEndpointTemplate[] = [
	"/v1/body_measurements",
	"/v1/body_measurements/:date",
	"/v1/exercise_history/:exerciseTemplateId",
	"/v1/exercise_templates",
	"/v1/exercise_templates/:exerciseTemplateId",
	"/v1/routine_folders",
	"/v1/routine_folders/:folderId",
	"/v1/routines",
	"/v1/routines/:routineId",
	"/v1/user/info",
	"/v1/workouts",
	"/v1/workouts/:workoutId",
	"/v1/workouts/count",
	"/v1/workouts/events",
];

export interface HevyEndpointResolution {
	readonly known: boolean;
	readonly canonical: HevyEndpointIdentity;
	readonly diagnostic: HevyDiagnosticEndpoint | undefined;
	readonly metric: HevyMetricEndpoint;
}

const STATIC_ENDPOINTS = new Set<HevyEndpointTemplate>([
	"/v1/body_measurements",
	"/v1/exercise_templates",
	"/v1/routine_folders",
	"/v1/routines",
	"/v1/user/info",
	"/v1/workouts",
	"/v1/workouts/count",
	"/v1/workouts/events",
]);

const DYNAMIC_ENDPOINTS: readonly (readonly [string, HevyEndpointTemplate])[] =
	[
		["/v1/body_measurements/", "/v1/body_measurements/:date"],
		["/v1/exercise_history/", "/v1/exercise_history/:exerciseTemplateId"],
		["/v1/exercise_templates/", "/v1/exercise_templates/:exerciseTemplateId"],
		["/v1/routine_folders/", "/v1/routine_folders/:folderId"],
		["/v1/routines/", "/v1/routines/:routineId"],
		["/v1/workouts/", "/v1/workouts/:workoutId"],
	];

function identityPath(value: string): string {
	const query = value.search(/[?#]/);
	return query < 0 ? value : value.slice(0, query);
}

/** Resolve a raw request path or a canonical template without exposing IDs. */
export function resolveHevyEndpoint(path: string): HevyEndpointResolution {
	const candidate = identityPath(path);
	let endpoint: HevyEndpointTemplate | undefined;
	if (STATIC_ENDPOINTS.has(candidate as HevyEndpointTemplate)) {
		endpoint = candidate as HevyEndpointTemplate;
	} else {
		for (const [prefix, template] of DYNAMIC_ENDPOINTS) {
			const id = candidate.slice(prefix.length);
			if (candidate.startsWith(prefix) && id.length > 0 && !id.includes("/")) {
				endpoint = template;
				break;
			}
		}
	}
	if (
		!endpoint &&
		HEVY_ENDPOINT_TEMPLATES.includes(candidate as HevyEndpointTemplate)
	) {
		endpoint = candidate as HevyEndpointTemplate;
	}
	return endpoint
		? {
				known: true,
				canonical: endpoint,
				diagnostic: endpoint,
				metric: endpoint,
			}
		: {
				known: false,
				canonical: "unknown",
				diagnostic: undefined,
				metric: "unknown",
			};
}

export function canonicalEndpointIdentity(path: string): HevyEndpointIdentity {
	return resolveHevyEndpoint(path).canonical;
}

export function diagnosticEndpointIdentity(
	path: string,
): HevyDiagnosticEndpoint | undefined {
	return resolveHevyEndpoint(path).diagnostic;
}

export function metricEndpointIdentity(path: string): HevyMetricEndpoint {
	return resolveHevyEndpoint(path).metric;
}

export type ExpectedGet404Outcome = "not_found" | "end_of_list";

const RESOURCE_404_ENDPOINTS = new Set<HevyEndpointTemplate>([
	"/v1/body_measurements/:date",
	"/v1/exercise_history/:exerciseTemplateId",
	"/v1/exercise_templates/:exerciseTemplateId",
	"/v1/routine_folders/:folderId",
	"/v1/routines/:routineId",
	"/v1/workouts/:workoutId",
]);
const LIST_404_ENDPOINTS = new Set<HevyEndpointTemplate>([
	"/v1/body_measurements",
	"/v1/exercise_templates",
	"/v1/routine_folders",
	"/v1/routines",
	"/v1/workouts",
	"/v1/workouts/events",
]);

/** Return the bounded meaning of a GET 404, if it is an expected absence. */
export function expectedGet404Outcome(
	endpoint: string,
	method: string,
	status: number | undefined,
	page?: number,
): ExpectedGet404Outcome | undefined {
	if (status !== 404 || method.toUpperCase() !== "GET") return undefined;
	const resolved = resolveHevyEndpoint(endpoint).canonical;
	if (RESOURCE_404_ENDPOINTS.has(resolved as HevyEndpointTemplate)) {
		return "not_found";
	}
	if (
		page !== undefined &&
		page > 1 &&
		LIST_404_ENDPOINTS.has(resolved as HevyEndpointTemplate)
	) {
		return "end_of_list";
	}
	return undefined;
}

export type Mutation404Policy = "expected" | "unexpected";
const MUTATION_404_ENDPOINTS = new Set<HevyEndpointTemplate>([
	"/v1/body_measurements",
	"/v1/body_measurements/:date",
	"/v1/exercise_templates",
	"/v1/routine_folders",
	"/v1/routines",
	"/v1/routines/:routineId",
	"/v1/workouts",
	"/v1/workouts/:workoutId",
]);

/** Mutating 404s are expected only for known mutable endpoint identities. */
export function mutation404Policy(
	endpoint: string,
	method: string,
	status: number | undefined,
): Mutation404Policy {
	return status === 404 &&
		method.toUpperCase() !== "GET" &&
		MUTATION_404_ENDPOINTS.has(
			resolveHevyEndpoint(endpoint).canonical as HevyEndpointTemplate,
		)
		? "expected"
		: "unexpected";
}

export function isExpectedMutation404(
	endpoint: string,
	method: string,
	status: number | undefined,
): boolean {
	return mutation404Policy(endpoint, method, status) === "expected";
}

const NON_RETRYABLE_CODES = new Set([
	HEVY_REQUEST_ABORTED_ERROR_CODE,
	HEVY_RETRY_EXHAUSTED_ERROR_CODE,
	HEVY_DEADLINE_EXCEEDED_ERROR_CODE,
]);

export function isTransientRetryStatus(status: number | undefined): boolean {
	return (
		status === undefined ||
		status === 408 ||
		status === 429 ||
		(status >= 500 && status <= 599)
	);
}

export function isTransientRetryCode(code: string | undefined): boolean {
	return code === undefined || !NON_RETRYABLE_CODES.has(code);
}

/** Shared status/code classification; execution layers still own retry budgets. */
export function isTransientRetryFailure(
	status: number | undefined,
	code?: string,
): boolean {
	return isTransientRetryCode(code) && isTransientRetryStatus(status);
}

/** Runtime-neutral fetch client used by the generated Hevy API operations. */
export type RequestConfig<TData = unknown> = {
	baseURL?: string;
	url?: string;
	method?: "GET" | "PUT" | "PATCH" | "POST" | "DELETE" | "OPTIONS" | "HEAD";
	path?: unknown;
	params?: unknown;
	query?: unknown;
	data?: TData | FormData;
	body?: TData | FormData;
	responseType?:
		| "arraybuffer"
		| "blob"
		| "document"
		| "json"
		| "text"
		| "stream";
	signal?: AbortSignal;
	headers?: [string, string][] | Record<string, string>;
};

export type ResponseConfig<TData = unknown> = {
	data: TData;
	status: number;
	statusText: string;
	headers: Headers;
};

let config: Partial<RequestConfig> = {};

export const getConfig = () => config;

export const setConfig = (nextConfig: Partial<RequestConfig>) => {
	config = nextConfig;
	return getConfig();
};

function normalizeHeaders(
	headers: RequestConfig["headers"],
): Record<string, string> {
	return Array.isArray(headers) ? Object.fromEntries(headers) : (headers ?? {});
}

export const mergeConfig = <T extends RequestConfig>(
	...configs: Array<Partial<T>>
): Partial<T> => {
	return configs.reduce<Partial<T>>((merged, nextConfig) => {
		return {
			...merged,
			...nextConfig,
			headers: {
				...normalizeHeaders(merged.headers),
				...normalizeHeaders(nextConfig.headers),
			},
		};
	}, {});
};

export type ResponseErrorConfig<TError = unknown> = TError;

export type Client = <TData, _TError = unknown, TVariables = unknown>(
	requestConfig: RequestConfig<TVariables>,
) => Promise<ResponseConfig<TData>>;

export const fetch = async <TData, _TError = unknown, TVariables = unknown>(
	paramsConfig: RequestConfig<TVariables>,
): Promise<ResponseConfig<TData>> => {
	const normalizedParams = new URLSearchParams();
	const requestConfig = mergeConfig(getConfig(), paramsConfig);
	const query = requestConfig.query ?? requestConfig.params;
	const bodyPayload = requestConfig.body ?? requestConfig.data;
	const pathParams = requestConfig.path;

	Object.entries(query || {}).forEach(([key, value]) => {
		if (value !== undefined) {
			normalizedParams.append(key, value === null ? "null" : value.toString());
		}
	});

	let resolvedPath = requestConfig.url ?? "";
	Object.entries(pathParams || {}).forEach(([key, value]) => {
		if (value !== undefined) {
			resolvedPath = resolvedPath.replaceAll(
				`{${key}}`,
				encodeURIComponent(value === null ? "null" : value.toString()),
			);
		}
	});

	let targetUrl = [requestConfig.baseURL, resolvedPath]
		.filter(Boolean)
		.join("");
	if (query) targetUrl += `?${normalizedParams}`;

	const response = await globalThis.fetch(targetUrl, {
		method: requestConfig.method?.toUpperCase(),
		body:
			bodyPayload instanceof FormData
				? bodyPayload
				: JSON.stringify(bodyPayload),
		signal: requestConfig.signal,
		headers: requestConfig.headers,
	});

	const data =
		[204, 205, 304].includes(response.status) || !response.body
			? {}
			: await response.json();

	return {
		data: data as TData,
		status: response.status,
		statusText: response.statusText,
		headers: response.headers,
	};
};

export default fetch;

