			fetch: fetchMock,
			maxGetRetries: 1,
		});

		const program = Effect.gen(function* () {
			const fiber = yield* client
				.requestEffect({ method: "GET", url: "/v1/user/info" })
				.pipe(Effect.forkChild);
			yield* Effect.yieldNow;
